/usr/bin/zsh -lc "rtk python3 -m compileall -q src validation.py && rtk PYTHONPATH=src python3 -c 'import register; assert len(register.ROUTES) == 2; assert register.resend_confirmation({\"email\": \"a@example.com\"}) == {\"ok\": True, \"queued\": True};
try:
    register.resend_confirmation(None)
except TypeError:
    pass
else:
    raise AssertionError(\"invalid payload was accepted\")' && rtk git diff --cached --check"

